using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Animation;
namespace OrbitLauncher;
public partial class MainWindow {
 static readonly CubicEase motionEase=new(){EasingMode=EasingMode.EaseOut};
 FrameworkElement? animatedPage;
 void ApplyMotionPreference(){Application.Current.Resources["ReduceMotion"]=settings.ReduceMotion;Application.Current.Resources["PopupMotion"]=settings.ReduceMotion?System.Windows.Controls.Primitives.PopupAnimation.None:System.Windows.Controls.Primitives.PopupAnimation.Fade;if(settings.ReduceMotion){if(animatedPage!=null){animatedPage.BeginAnimation(OpacityProperty,null);animatedPage.Opacity=1;if(animatedPage.RenderTransform is TranslateTransform t){t.BeginAnimation(TranslateTransform.YProperty,null);t.Y=0;}}if(HeroArtwork?.RenderTransform is TranslateTransform hero){hero.BeginAnimation(TranslateTransform.XProperty,null);hero.BeginAnimation(TranslateTransform.YProperty,null);hero.X=hero.Y=0;}}}
 void AnimatePage(string name){FrameworkElement target=name switch{"Library"=>LibraryPage,"Skins"=>SkinsPage,"Mods"=>ModsPage,"Worlds"=>FilesPage,"Settings"=>SettingsPage,"Logs"=>LogsPage,_=>HomePage};animatedPage=target;target.BeginAnimation(OpacityProperty,null);target.RenderTransform=new TranslateTransform();if(settings.ReduceMotion){target.Opacity=1;return;}target.BeginAnimation(OpacityProperty,new DoubleAnimation(.4,1,TimeSpan.FromMilliseconds(240)){EasingFunction=motionEase});((TranslateTransform)target.RenderTransform).BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(12,0,TimeSpan.FromMilliseconds(310)){EasingFunction=motionEase});}
 void AnimateNavigation(Button button,bool active){button.ApplyTemplate();var old=(button.Background as SolidColorBrush)?.Color??Colors.Transparent;var color=active?Color.FromRgb(22,58,53):Colors.Transparent;var brush=new SolidColorBrush(color);button.Background=brush;button.Foreground=new SolidColorBrush(active?Color.FromRgb(121,255,208):Color.FromRgb(167,189,205));var duration=TimeSpan.FromMilliseconds(settings.ReduceMotion?0:220);brush.BeginAnimation(SolidColorBrush.ColorProperty,new ColorAnimation(old,color,duration){EasingFunction=motionEase});if(button.Template.FindName("ActiveRail",button) is Border rail)rail.BeginAnimation(OpacityProperty,new DoubleAnimation(active?1:0,duration){EasingFunction=motionEase});}
 void HeroPointer_Move(object sender,MouseEventArgs e){if(settings.ReduceMotion||HeroArtwork.RenderTransform is not TranslateTransform t)return;var grid=(FrameworkElement)sender;var p=e.GetPosition(grid);double x=(p.X/Math.Max(1,grid.ActualWidth)-.5)*10,y=(p.Y/Math.Max(1,grid.ActualHeight)-.5)*7;t.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(x,TimeSpan.FromMilliseconds(220)){EasingFunction=motionEase});t.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(y,TimeSpan.FromMilliseconds(220)){EasingFunction=motionEase});}
 void HeroPointer_Leave(object sender,MouseEventArgs e){if(HeroArtwork.RenderTransform is not TranslateTransform t)return;var d=TimeSpan.FromMilliseconds(settings.ReduceMotion?0:300);t.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(0,d){EasingFunction=motionEase});t.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(0,d){EasingFunction=motionEase});}
}
